        class MazeGenerator {
            constructor(width, height, engine) {
                this.engine = engine;
                this.width = width;
                this.height = height;
                this.map = Array(height).fill().map(() => Array(width).fill(1));
            }
            
            generate() {
                const stack = [];
                const startX = 1;
                const startY = 1;
                this.map[startY][startX] = 0;
                stack.push([startX, startY]);
                
                while (stack.length > 0) {
                    const current = stack[stack.length - 1];
                    const cx = current[0];
                    const cy = current[1];
                    
                    const dirs = [[0,-2],[2,0],[0,2],[-2,0]];
                    dirs.sort(() => Math.random() - 0.5);
                    
                    let moved = false;
                    for (let d of dirs) {
                        const nx = cx + d[0];
                        const ny = cy + d[1];
                        
                        if (nx > 0 && nx < this.width - 1 && ny > 0 && ny < this.height - 1 && this.map[ny][nx] === 1) {
                            this.map[cy + d[1]/2][cx + d[0]/2] = 0;
                            this.map[ny][nx] = 0;
                            stack.push([nx, ny]);
                            moved = true;
                            break;
                        }
                    }
                    
                    if (!moved) {
                        stack.pop();
                    }
                }
                
                for (let i = 0; i < 20; i++) {
                    const rx = Math.floor(Math.random() * (this.width - 10)) + 1;
                    const ry = Math.floor(Math.random() * (this.height - 10)) + 1;
                    const template = ROOM_TEMPLATES[Math.floor(Math.random() * ROOM_TEMPLATES.length)];
                    
                    for (let y = 0; y < 8; y++) {
                        for (let x = 0; x < 8; x++) {
                            if (ry + y < this.height - 1 && rx + x < this.width - 1) {
                                if (template[y][x] === 0) {
                                    this.map[ry + y][rx + x] = 0;
                                }
                            }
                        }
                    }
                }
                
                this.map[1][1] = 0;
                this.map[1][2] = 0;
                this.map[2][1] = 0;
                
                let ex = this.width - 2;
                let ey = this.height - 2;
                this.map[ey][ex] = 5;
                this.map[ey][ex-1] = 0;
                this.map[ey-1][ex] = 0;
                
                return {
                    map: this.map,
                    start: { x: 1.5, y: 1.5 },
                    exit: { x: ex + 0.5, y: ey + 0.5 }
                };
            }
        }



        class Vector2 {
            constructor(x = 0, y = 0) {
                this.x = x;
                this.y = y;
            }

            add(v) {
                this.x += v.x;
                this.y += v.y;
                return this;
            }

            sub(v) {
                this.x -= v.x;
                this.y -= v.y;
                return this;
            }

            mult(n) {
                this.x *= n;
                this.y *= n;
                return this;
            }

            div(n) {
                this.x /= n;
                this.y /= n;
                return this;
            }

            mag() {
                return Math.sqrt(this.x * this.x + this.y * this.y);
            }

            magSq() {
                return this.x * this.x + this.y * this.y;
            }

            normalize() {
                const m = this.mag();
                if (m !== 0 && m !== 1) {
                    this.div(m);
                }
                return this;
            }

            dist(v) {
                const dx = this.x - v.x;
                const dy = this.y - v.y;
                return Math.sqrt(dx * dx + dy * dy);
            }

            copy() {
                return new Vector2(this.x, this.y);
            }

            set(x, y) {
                this.x = x;
                this.y = y;
                return this;
            }

            static sub(v1, v2) {
                return new Vector2(v1.x - v2.x, v1.y - v2.y);
            }
        }

        const MathUtils = {
            clamp: (val, min, max) => Math.max(min, Math.min(max, val))
        };

        const NoiseGen = (function() {
            const p = [
                151,160,137,91,90,15,131,13,201,95,96,53,194,233,7,225,140,36,103,30,69,142,8,99,37,240,21,10,23,
                190,6,148,247,120,234,75,0,26,197,62,94,252,219,203,117,35,11,32,57,177,33,88,237,149,56,87,174,
                20,125,136,171,168,68,175,74,165,71,134,139,48,27,166,77,146,158,231,83,111,229,122,60,211,133,
                230,220,105,92,41,55,46,245,40,244,102,143,54,65,25,63,161,1,216,80,73,209,76,132,187,208,89,
                18,169,200,196,135,130,116,188,159,86,164,100,109,198,173,186,3,64,52,217,226,250,124,123,5,202,
                38,147,118,126,255,82,85,212,207,206,59,227,47,16,58,17,182,189,28,42,223,183,170,213,119,248,152,
                2,44,154,163,70,221,153,101,155,167,43,172,9,129,22,39,253,19,98,108,110,79,113,224,232,178,185,
                112,104,218,246,97,228,251,34,242,193,238,210,144,12,191,179,162,241,81,51,145,235,249,14,239,107,
                49,192,214,31,181,199,106,157,184,84,204,176,115,121,50,45,127,4,150,254,138,236,205,93,222,114,
                67,29,24,72,243,141,128,195,78,66,215,61,156,180
            ];
            
            const perm = new Array(512);
            for(let i = 0; i < 512; i++) {
                perm[i] = p[i & 255];
            }
            
            const fade = t => t * t * t * (t * (t * 6 - 15) + 10);
            
            const lerp = (t, a, b) => a + t * (b - a);
            
            const grad = (hash, x, y, z) => {
                const h = hash & 15;
                const u = h < 8 ? x : y;
                const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
                return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
            };
            
            return {
                get: function(x, y, z) {
                    let X = Math.floor(x) & 255;
                    let Y = Math.floor(y) & 255;
                    let Z = Math.floor(z) & 255;
                    
                    x -= Math.floor(x);
                    y -= Math.floor(y);
                    z -= Math.floor(z);
                    
                    let u = fade(x);
                    let v = fade(y);
                    let w = fade(z);
                    
                    let A = perm[X] + Y;
                    let AA = perm[A] + Z;
                    let AB = perm[A + 1] + Z;
                    let B = perm[X + 1] + Y;
                    let BA = perm[B] + Z;
                    let BB = perm[B + 1] + Z;
                    
                    return lerp(w,
                        lerp(v,
                            lerp(u, grad(perm[AA], x, y, z), grad(perm[BA], x - 1, y, z)),
                            lerp(u, grad(perm[AB], x, y - 1, z), grad(perm[BB], x - 1, y - 1, z))
                        ),
                        lerp(v,
                            lerp(u, grad(perm[AA + 1], x, y, z - 1), grad(perm[BA + 1], x - 1, y, z - 1)),
                            lerp(u, grad(perm[AB + 1], x, y - 1, z - 1), grad(perm[BB + 1], x - 1, y - 1, z - 1))
                        )
                    );
                }
            };
        })();

        const Settings = {
            musicVol: 0.5,
            sfxVol: 1.0,
            quality: 'HIGH',
            swarm: 'NORMAL',
            speed: 'ZEN',
            
            parseVol(valStr) {
                if (valStr === 'OFF') {
                    return 0;
                }
                return parseInt(valStr.replace('%', '')) / 100;
            }
        };

        const customMusicPlayer = new Audio();
        customMusicPlayer.loop = true;
        customMusicPlayer.volume = Settings.musicVol;

        document.getElementById('btn-upload-music').addEventListener('click', () => {
            document.getElementById('music-upload').click();
        });

        document.getElementById('music-upload').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (file) {
                const url = URL.createObjectURL(file);
                customMusicPlayer.src = url;
                customMusicPlayer.play().catch(err => console.log(err));
                
                let displayName = file.name;
                if (displayName.length > 15) {
                    displayName = displayName.substring(0, 12) + '...';
                }
                document.getElementById('btn-upload-music').innerText = displayName;
            }
        });

        
        document.getElementById('set-music').addEventListener('input', (e) => {
            Settings.musicVol = parseInt(e.target.value) / 100;
            customMusicPlayer.volume = Settings.musicVol;
        });
        document.getElementById('set-sfx').addEventListener('input', (e) => {
            Settings.sfxVol = parseInt(e.target.value) / 100;
            if (window.Synth) window.Synth.updateVolumes();
        });

        document.querySelectorAll('.stepper').forEach(stepper => {
            const options = stepper.getAttribute('data-options').split(',');
            let currentIndex = options.indexOf(stepper.querySelector('span').innerText);
            
            if (currentIndex === -1) {
                currentIndex = 0;
            }
            
            stepper.addEventListener('click', () => {
                currentIndex = (currentIndex + 1) % options.length;
                const newVal = options[currentIndex];
                stepper.querySelector('span').innerText = newVal;
                
                if (stepper.id === 'set-music') {
                    Settings.musicVol = Settings.parseVol(newVal);
                    customMusicPlayer.volume = Settings.musicVol;
                }
                
                if (stepper.id === 'set-sfx') {
                    Settings.sfxVol = Settings.parseVol(newVal);
                    if (Synth) {
                        Synth.updateVolumes();
                    }
                }
                
                if (stepper.id === 'set-quality') {
                    Settings.quality = newVal;
                }
                
                if (stepper.id === 'set-swarm') {
                    Settings.swarm = newVal;
                }
                
                if (stepper.id === 'set-speed') {
                    Settings.speed = newVal;
                }
            });
        });

        class AudioSynth {
            constructor() {
                this.ctx = null;
                this.sfxGain = null;
                this.initialized = false;
                this.scale = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99, 880.00, 1046.50];
                this.horrorNodes = [];
            }

            init() {
                if (this.initialized) {
                    return;
                }
                
                const AudioContext = window.AudioContext || window.webkitAudioContext;
                if (!AudioContext) {
                    return;
                }
                
                this.ctx = new AudioContext();
                this.sfxGain = this.ctx.createGain();
                this.sfxGain.connect(this.ctx.destination);
                
                this.updateVolumes();
                this.initialized = true;
            }

            updateVolumes() {
                if (!this.ctx) {
                    return;
                }
                this.sfxGain.gain.setTargetAtTime(Settings.sfxVol * 0.4, this.ctx.currentTime, 0.1);
            }

            playCapture(comboMultiplier) {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                const baseNote = Math.min(this.scale.length - 1, 3 + Math.floor(comboMultiplier / 2));
                
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(this.scale[baseNote] || 880, this.ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime((this.scale[baseNote] || 880) * 1.5, this.ctx.currentTime + 0.1);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(0.8, this.ctx.currentTime + 0.02);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.4);
            }

            playComboUp() {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                osc.type = 'square';
                osc.frequency.setValueAtTime(440, this.ctx.currentTime);
                osc.frequency.setValueAtTime(554.37, this.ctx.currentTime + 0.1);
                osc.frequency.setValueAtTime(659.25, this.ctx.currentTime + 0.2);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(0.3, this.ctx.currentTime + 0.05);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.5);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.6);
            }

            startHorrorAudio() {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                // Breath (White noise + bandpass)
                const bufferSize = this.ctx.sampleRate * 2;
                const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
                const data = buffer.getChannelData(0);
                
                for (let i = 0; i < bufferSize; i++) {
                    data[i] = Math.random() * 2 - 1;
                }
                
                const noise = this.ctx.createBufferSource();
                noise.buffer = buffer;
                noise.loop = true;
                
                const filter = this.ctx.createBiquadFilter();
                filter.type = 'bandpass';
                filter.frequency.value = 500;
                filter.Q.value = 1.0;
                
                const lfo = this.ctx.createOscillator();
                lfo.frequency.value = 0.2;
                
                const lfoGain = this.ctx.createGain();
                lfoGain.gain.value = 400;
                
                lfo.connect(lfoGain);
                lfoGain.connect(filter.frequency);
                
                const breathGain = this.ctx.createGain();
                breathGain.gain.value = 0.5;
                
                noise.connect(filter);
                filter.connect(breathGain);
                breathGain.connect(this.sfxGain);
                
                noise.start();
                lfo.start();
                
                
                const osc1 = this.ctx.createOscillator();
                const osc2 = this.ctx.createOscillator();
                osc1.type = 'sine';
                osc2.type = 'sawtooth';
                osc1.frequency.value = 40;
                osc2.frequency.value = 41.5;
                
                const droneFilter = this.ctx.createBiquadFilter();
                droneFilter.type = 'lowpass';
                droneFilter.frequency.value = 100;
                
                const droneGain = this.ctx.createGain();
                droneGain.gain.value = 1.5;
                
                osc1.connect(droneFilter);
                osc2.connect(droneFilter);
                droneFilter.connect(droneGain);
                droneGain.connect(this.sfxGain);
                
                osc1.start();
                osc2.start();
                
                this.horrorNodes.push(noise, lfo, osc1, osc2);
                
                this.heartbeatTimer = 0;
                this.heartbeatActive = false;
            }

            updateHorrorAudio(dt) {
                if (!this.initialized || Settings.sfxVol === 0) {
                    return;
                }
                
                this.heartbeatTimer -= dt;
                
                if (!this.heartbeatActive && Math.random() < 0.005) {
                    this.heartbeatActive = true;
                    this.heartbeatTimer = 5000 + Math.random() * 5000;
                    this.heartbeatInterval = 300;
                }
                
                if (this.heartbeatActive) {
                    if (this.heartbeatTimer <= 0) {
                        this.heartbeatActive = false;
                    }
                    
                    this.heartbeatInterval -= dt;
                    
                    if (this.heartbeatInterval <= 0) {
                        this.playHeartbeat();
                        this.heartbeatInterval = 350 + Math.random() * 100;
                    }
                }
            }

            playHeartbeat() {
                const osc = this.ctx.createOscillator();
                const env = this.ctx.createGain();
                
                osc.type = 'sine';
                osc.frequency.setValueAtTime(40, this.ctx.currentTime);
                osc.frequency.exponentialRampToValueAtTime(10, this.ctx.currentTime + 0.3);
                
                env.gain.setValueAtTime(0, this.ctx.currentTime);
                env.gain.linearRampToValueAtTime(1.0, this.ctx.currentTime + 0.05);
                env.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);
                
                osc.connect(env);
                env.connect(this.sfxGain);
                
                osc.start(this.ctx.currentTime);
                osc.stop(this.ctx.currentTime + 0.4);
            }

            stopHorrorAudio() {
                this.horrorNodes.forEach(n => n.stop());
                this.horrorNodes = [];
                this.heartbeatActive = false;
            }
        }
        
        const Synth = new AudioSynth();

        class InputManager {
            constructor() {
                this.pointerPos = new Vector2(-1000, -1000);
                this.isPointerDown = false;
                this.keys = {};
                this.listeners = [];
                this.ambientGlow = document.getElementById('ambientGlow');
                
                this.bindEvents();
            }

            bindEvents() {
                const down = (e) => this.handlePointerDown(e);
                const move = (e) => this.handlePointerMove(e);
                const up = (e) => {
                    this.isPointerDown = false;
                    this.emit('up', this.pointerPos);
                };
                
                window.addEventListener('pointerdown', down);
                window.addEventListener('pointermove', move);
                window.addEventListener('pointerup', up);
                
                window.addEventListener('touchstart', (e) => {
                    if (e.target.tagName !== 'BUTTON' && !e.target.classList.contains('stepper')) {
                        e.preventDefault();
                    }
                    down(e.touches[0]);
                }, { passive: false });
                
                window.addEventListener('touchmove', (e) => {
                    e.preventDefault();
                    move(e.touches[0]);
                }, { passive: false });
                
                window.addEventListener('touchend', up);
                
                window.addEventListener('keydown', (e) => {
                    this.keys[e.key.toLowerCase()] = true;
                    
                    if (e.code === 'Escape' || e.code === 'Space') {
                        this.emit('pauseToggle');
                    }
                    
                                        if (e.key.toLowerCase() === 'm') {
                        if (customMusicPlayer.paused) {
                            customMusicPlayer.play().catch(err=>{});
                            customMusicPlayer.muted = false;
                        } else {
                            customMusicPlayer.pause();
                        }
                        const inst = document.getElementById('instruction-hud');
                        if (inst) {
                            inst.innerText = customMusicPlayer.paused ? "Music Paused (M)" : "Music Playing (M)";
                            setTimeout(() => {
                                if (window.currentGameEngine) {
                                    inst.innerText = window.currentGameEngine.currentState === 'PLAYING_HORROR' 
                                        ? "Use WASD to move. Mouse to look. Find the green light." 
                                        : "Press and hold to track fireflies";
                                }
                            }, 2000);
                        }
                    }
                });
                
                window.addEventListener('keyup', (e) => {
                    this.keys[e.key.toLowerCase()] = false;
                });
                
                window.addEventListener('mousemove', (e) => {
                    if (document.pointerLockElement === document.getElementById('game-canvas')) {
                        this.emit('mouseLook', { x: e.movementX, y: e.movementY });
                    }
                });
            }

            handlePointerDown(e) {
                Synth.init();
                
                if (window.currentGameEngine && window.currentGameEngine.currentState !== 'PLAYING_HORROR') {
                    if (customMusicPlayer.src && customMusicPlayer.paused && Settings.musicVol > 0 && !customMusicPlayer.muted) {
                        customMusicPlayer.play().catch(() => {});
                    }
                }
                
                this.isPointerDown = true;
                this.updatePointerPos(e);
                this.emit('down', this.pointerPos);
                
                if (window.currentGameEngine && window.currentGameEngine.currentState === 'PLAYING_HORROR') {
                    const canvas = document.getElementById('game-canvas');
                    canvas.requestPointerLock = canvas.requestPointerLock || canvas.mozRequestPointerLock;
                    canvas.requestPointerLock();
                }
            }

            handlePointerMove(e) {
                this.updatePointerPos(e);
            }

            updatePointerPos(e) {
                if (!e) {
                    return;
                }
                
                this.pointerPos.set(e.clientX, e.clientY);
                
                if (this.ambientGlow) {
                    this.ambientGlow.style.left = `${e.clientX}px`;
                    this.ambientGlow.style.top = `${e.clientY}px`;
                }
            }

            on(event, callback) {
                this.listeners.push({ event, callback });
            }

            emit(event, data) {
                this.listeners.forEach(l => {
                    if (l.event === event) {
                        l.callback(data);
                    }
                });
            }
        }
        
        window.Input = new InputManager();
        const Input = window.Input;

        class Particle {
            constructor(x, y, r, g, b, multiplier) {
                this.pos = new Vector2(x, y);
                this.vel = new Vector2();
                
                const angle = Math.random() * Math.PI * 2;
                const speed = (Math.random() * 6 + 2) * (1 + (multiplier * 0.05));
                
                this.vel.x = Math.cos(angle) * speed;
                this.vel.y = Math.sin(angle) * speed;
                
                this.color = `${r}, ${g}, ${b}`;
                this.life = 1.0;
                this.decay = Math.random() * 0.04 + 0.01;
                this.size = Math.random() * 3 + 1;
            }

            update() {
                this.pos.add(this.vel);
                this.vel.mult(0.92);
                this.life -= this.decay;
            }

            draw(ctx) {
                if (this.life <= 0) {
                    return;
                }
                
                ctx.beginPath();
                ctx.arc(this.pos.x, this.pos.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(${this.color}, ${this.life})`;
                
                if (Settings.quality === 'HIGH') {
                    ctx.shadowBlur = 6;
                    ctx.shadowColor = `rgba(${this.color}, ${this.life})`;
                }
                
                ctx.fill();
                ctx.shadowBlur = 0;
            }
        }

        class FloatingText {
            constructor(x, y, text, colorStr, scale) {
                this.pos = new Vector2(x, y);
                this.text = text;
                this.color = colorStr;
                this.life = 1.0;
                this.vy = -1.2;
                this.scale = scale || 1;
            }

            update() {
                this.pos.y += this.vy;
                this.life -= 0.02;
            }

            draw(ctx) {
                if (this.life <= 0) {
                    return;
                }
                
                ctx.font = `bold ${22 * this.scale}px var(--font-main)`;
                ctx.fillStyle = `rgba(${this.color}, ${this.life})`;
                ctx.textAlign = 'center';
                
                if (Settings.quality === 'HIGH') {
                    ctx.shadowBlur = 8;
                    ctx.shadowColor = `rgba(${this.color}, ${this.life})`;
                }
                
                ctx.fillText(this.text, this.pos.x, this.pos.y);
                ctx.shadowBlur = 0;
            }
        }

        class Firefly {
            constructor(engine, isInitialSpawn, forceRed = false) {
                this.engine = engine;
                this.id = Math.random() * 10000;
                this.pos = new Vector2();
                this.isRed = forceRed;
                
                this.reset(isInitialSpawn);
            }

            reset(isInitialSpawn = false) {
                this.seedOffset = Math.random() * 10000;
                this.phase = Math.random() * Math.PI * 2;
                
                if (isInitialSpawn) {
                    this.pos.x = Math.random() * this.engine.width;
                    this.pos.y = Math.random() * this.engine.height;
                } else {
                    if (Math.random() > 0.8) {
                        this.pos.x = (Math.random() > 0.5) ? -50 : this.engine.width + 50;
                        this.pos.y = Math.random() * this.engine.height;
                    } else {
                        this.pos.x = Math.random() * this.engine.width;
                        this.pos.y = this.engine.height + 50 + Math.random() * 100;
                    }
                }
                
                if (this.isRed) {
                    this.type = 'red';
                    this.r = 255;
                    this.g = 40;
                    this.b = 40;
                    this.size = 6.0;
                    this.speed = 0.5; // Starts slow
                    this.points = 0;
                    this.trackSpeedMultiplier = 5.0;
                    this.hitRadius = 9999;
                    this.redLife = 0;
                } else {
                    const roll = Math.random();
                    if (roll > 0.95) {
                        this.type = 'gold';
                        this.r = 249;
                        this.g = 226;
                        this.b = 175;
                        this.size = 3.5;
                        this.speed = 2.0;
                        this.points = 150;
                        this.trackSpeedMultiplier = 0.9;
                        this.hitRadius = 100; // Increased
                    } else if (roll > 0.70) {
                        this.type = 'purple';
                        this.r = 203;
                        this.g = 166;
                        this.b = 247;
                        this.size = 2.5;
                        this.speed = 1.4;
                        this.points = 50;
                        this.trackSpeedMultiplier = 1.1;
                        this.hitRadius = 110; // Increased
                    } else {
                        this.type = 'blue';
                        this.r = 137;
                        this.g = 180;
                        this.b = 250;
                        this.size = 1.8;
                        this.speed = 0.8;
                        this.points = 20;
                        this.trackSpeedMultiplier = 1.5;
                        this.hitRadius = 120; // Increased
                    }
                }
                
                this.trackProgress = 0;
                this.isBeingTracked = false;
                this.panicMultiplier = 1.0;
                this.isActive = true;
            }

            update(time, deltaTime) {
                if (!this.isActive) {
                    return;
                }

                if (this.isRed) {
                    this.redLife += deltaTime;
                    
                    if (this.redLife > 2000) {
                        this.speed = Math.min(25.0, this.speed + 0.6);
                        const target = Input.pointerPos.x > 0 ? Input.pointerPos : new Vector2(this.engine.width / 2, this.engine.height / 2);
                        const dir = Vector2.sub(target, this.pos).normalize();
                        this.pos.add(dir.mult(this.speed));
                        
                        if (this.pos.dist(Input.pointerPos) < 150) {
                            this.isBeingTracked = true;
                            this.trackProgress += 1000;
                        }
                    } else {
                        this.isBeingTracked = false;
                        this.pos.x += Math.sin(this.redLife * 0.005) * 0.5;
                        this.pos.y += Math.cos(this.redLife * 0.005) * 0.5;
                    }
                } else {
                    const hasRed = this.engine.fireflies.some(f => f.isRed && f.isActive);
                    
                    if (hasRed) {
                                                const target = Input.pointerPos.x > 0 ? Input.pointerPos : new Vector2(this.engine.width / 2, this.engine.height / 2);
                        const away = Vector2.sub(this.pos, target).normalize();
                        this.pos.add(away.mult(this.speed * 4));
                        this.phase += 0.2;
                    } else {
                        const timeScale = this.type === 'purple' ? 0.0012 : 0.0007;
                        const nx = NoiseGen.get(this.id, time * timeScale, this.seedOffset);
                        const ny = NoiseGen.get(this.id + 100, time * timeScale, this.seedOffset);
                        
                        let speedSettingMult = 1.0;
                        if (Settings.speed === 'FAST') {
                            speedSettingMult = 1.5;
                        }
                        if (Settings.speed === 'ZEN') {
                            speedSettingMult = 0.7;
                        }
                        
                        const currentSpeed = this.speed * this.engine.difficulty * this.panicMultiplier * speedSettingMult;
                        
                        this.pos.x += nx * 4 * currentSpeed;
                        this.pos.y += ny * 4 * currentSpeed - (0.5 * currentSpeed);
                        this.phase += 0.05;
                    }
                    
                    if (this.pos.y < -150 || this.pos.x < -150 || this.pos.x > this.engine.width + 150 || this.pos.y > this.engine.height + 250) {
                        this.reset(false);
                    }
                    
                    this.isBeingTracked = false;
                    
                    if (Input.isPointerDown && this.pos.dist(Input.pointerPos) < this.hitRadius) {
                        this.isBeingTracked = true;
                    }
                }

                if (this.isBeingTracked) {
                    this.trackProgress += (80 * this.trackSpeedMultiplier) * (deltaTime / 1000);
                    
                    if (!this.isRed) {
                        this.panicMultiplier = MathUtils.clamp(this.panicMultiplier + 0.02, 1.0, 2.5);
                    }
                    
                    if (this.trackProgress >= 100) {
                        this.capture();
                    }
                } else {
                    this.trackProgress -= 180 * (deltaTime / 1000);
                    this.trackProgress = MathUtils.clamp(this.trackProgress, 0, 100);
                    
                    if (!this.isRed) {
                        this.panicMultiplier = MathUtils.clamp(this.panicMultiplier - 0.05, 1.0, 2.5);
                    }
                }
            }

            capture() {
                this.isActive = false;
                this.engine.onFireflyCaptured(this);
                if (!this.isRed) {
                    this.reset(false);
                }
            }

            draw(ctx) {
                if (!this.isActive) {
                    return;
                }
                
                const alpha = (Math.sin(this.phase) + 1) / 2 * 0.6 + 0.4;
                
                ctx.beginPath();
                ctx.arc(this.pos.x, this.pos.y, this.size * 1.5, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(${this.r}, ${this.g}, ${this.b}, ${alpha})`;
                
                if (Settings.quality === 'HIGH' || this.isRed) {
                    ctx.shadowBlur = this.type === 'gold' ? 20 : (this.isRed ? 60 : 10);
                    ctx.shadowColor = `rgba(${this.r}, ${this.g}, ${this.b}, ${alpha})`;
                }
                
                ctx.fill();
                ctx.shadowBlur = 0;

                if (this.trackProgress > 0 && !this.isRed) {
                    const radius = this.hitRadius * 0.7;
                    
                    ctx.beginPath();
                    ctx.arc(this.pos.x, this.pos.y, radius, 0, Math.PI * 2);
                    ctx.strokeStyle = `rgba(${this.r}, ${this.g}, ${this.b}, 0.2)`;
                    ctx.lineWidth = 2;
                    ctx.stroke();
                    
                    const startAngle = -Math.PI / 2;
                    const endAngle = startAngle + (Math.PI * 2 * (this.trackProgress / 100));
                    
                    ctx.beginPath();
                    ctx.arc(this.pos.x, this.pos.y, radius, startAngle, endAngle);
                    ctx.strokeStyle = `rgba(${this.r}, ${this.g}, ${this.b}, 0.9)`;
                    ctx.lineWidth = 4;
                    ctx.lineCap = 'round';
                    
                    if (Settings.quality === 'HIGH') {
                        ctx.shadowBlur = 8;
                        ctx.shadowColor = `rgba(${this.r}, ${this.g}, ${this.b}, 1)`;
                    }
                    
                    ctx.stroke();
                    ctx.shadowBlur = 0;
                }
            }
        }

        class BackroomsEngine {
            constructor(width, height, engine) {
                this.engine = engine;
                this.width = width;
                this.height = height;
                this.mapWidth = 32;
                this.mapHeight = 32;
                this.map = [];
                
                this.selectRandomMaze();
                
                this.pos = { x: 1.5, y: 1.5 };
                this.dir = { x: 1, y: 0 };
                this.plane = { x: 0, y: 0.66 };

                this.pitch = 0;
                
                this.exitPos = {x: this.mapWidth - 1.5, y: this.mapHeight - 1.5};
                this.monster = {
                    x: -1,
                    y: -1,
                    state: 'hidden',
                    timer: 1000,
                    seenTimer: 0
                };
                
                this.zBuffer = new Array(width).fill(0);
                this.lightRadius = 3.8; // Adjusted light radius for flashlight
                
                this.mouseLookHandler = (movement) => {
                    const movX = typeof movement === 'number' ? movement : movement.x;
                    const movY = typeof movement === 'number' ? 0 : movement.y;
                    
                    const rotSpeed = movX * 0.002;
                    this.pitch -= movY * 2.0;
                    this.pitch = Math.max(-this.height/2, Math.min(this.height/2, this.pitch));
                    
                    const oldDirX = this.dir.x;
                    
                    this.dir.x = this.dir.x * Math.cos(rotSpeed) - this.dir.y * Math.sin(rotSpeed);
                    this.dir.y = oldDirX * Math.sin(rotSpeed) + this.dir.y * Math.cos(rotSpeed);
                    
                    const oldPlaneX = this.plane.x;
                    this.plane.x = this.plane.x * Math.cos(rotSpeed) - this.plane.y * Math.sin(rotSpeed);
                    this.plane.y = oldPlaneX * Math.sin(rotSpeed) + this.plane.y * Math.cos(rotSpeed);
                };
                
                Input.on('mouseLook', this.mouseLookHandler);
            }

            destroy() {
                Input.listeners = Input.listeners.filter(l => l.callback !== this.mouseLookHandler);
            }

            selectRandomMaze() {
                this.mapWidth = 31;
                this.mapHeight = 31;
                const gen = new MazeGenerator(this.mapWidth, this.mapHeight);
                const res = gen.generate();
                this.map = res.map;
                this.map[this.mapHeight - 2][this.mapWidth - 2] = 2; 
                this.map[this.mapHeight - 2][this.mapWidth - 3] = 0;
                this.map[this.mapHeight - 3][this.mapWidth - 2] = 0;
                this.map[this.mapHeight - 2][this.mapWidth - 2] = 2; 
                this.map[this.mapHeight - 2][this.mapWidth - 3] = 0;
                this.map[this.mapHeight - 3][this.mapWidth - 2] = 0;
            }

            update(deltaTime) {
                const moveSpeed = (deltaTime / 1000) * 3.5;
                
                let moveStep = 0;
                let strafeStep = 0;
                
                if (Input.keys['w'] || Input.keys['arrowup']) {
                    moveStep = moveSpeed;
                }
                if (Input.keys['s'] || Input.keys['arrowdown']) {
                    moveStep = -moveSpeed;
                }
                if (Input.keys['a'] || Input.keys['arrowleft']) {
                    strafeStep = -moveSpeed;
                }
                if (Input.keys['d'] || Input.keys['arrowright']) {
                    strafeStep = moveSpeed;
                }
                

                const padding = 0.25;
                if (moveStep !== 0) {
                    let moveX = this.dir.x * moveStep;
                    let moveY = this.dir.y * moveStep;
                    if (this.map[Math.floor(this.pos.y)][Math.floor(this.pos.x + moveX + Math.sign(moveX) * padding)] === 0) {
                        this.pos.x += moveX;
                    }
                    if (this.map[Math.floor(this.pos.y + moveY + Math.sign(moveY) * padding)][Math.floor(this.pos.x)] === 0) {
                        this.pos.y += moveY;
                    }
                }
                
                if (strafeStep !== 0) {
                    let moveX = this.plane.x * strafeStep;
                    let moveY = this.plane.y * strafeStep;
                    if (this.map[Math.floor(this.pos.y)][Math.floor(this.pos.x + moveX + Math.sign(moveX) * padding)] === 0) {
                        this.pos.x += moveX;
                    }
                    if (this.map[Math.floor(this.pos.y + moveY + Math.sign(moveY) * padding)][Math.floor(this.pos.x)] === 0) {
                        this.pos.y += moveY;
                    }
                }

                
                
                                const distToExit = Math.sqrt(Math.pow(this.exitPos.x - this.pos.x, 2) + Math.pow(this.exitPos.y - this.pos.y, 2));
                if (distToExit < 1.2) {
                    return true;
                }
                if (this.monster.state === 'hidden') {
                    this.monster.timer -= deltaTime;
                    if (this.monster.timer <= 0 && Math.random() < 0.2) {
                        const spawnDist = 4.0;
                        const mx = this.pos.x - this.dir.x * spawnDist;
                        const my = this.pos.y - this.dir.y * spawnDist;
                        
                        if (mx > 0 && mx < this.mapWidth && my > 0 && my < this.mapHeight) {
                            if (this.map[Math.floor(my)][Math.floor(mx)] === 0) {
                                this.monster.x = mx;
                                this.monster.y = my;
                                this.monster.state = 'watching';
                                this.monster.seenTimer = 0;
                            }
                        }
                    }
                }
                
                Synth.updateHorrorAudio(deltaTime);
                
                if (Math.floor(this.pos.x) === this.mapWidth - 2 && Math.floor(this.pos.y) === this.mapHeight - 2) {
                    return true;
                }
                
                return false;
            }

            render(ctx) {
                ctx.fillStyle = "#020202";
                ctx.fillRect(0, 0, this.width, this.height);
                
                const res = 4;
                
                for (let x = 0; x < this.width; x += res) {
                    const cameraX = 2 * x / this.width - 1;
                    const rayDirX = this.dir.x + this.plane.x * cameraX;
                    const rayDirY = this.dir.y + this.plane.y * cameraX;
                    
                    let mapX = Math.floor(this.pos.x);
                    let mapY = Math.floor(this.pos.y);
                    
                    let sideDistX;
                    let sideDistY;
                    
                    const deltaDistX = Math.abs(1 / rayDirX);
                    const deltaDistY = Math.abs(1 / rayDirY);
                    
                    let perpWallDist;
                    let stepX;
                    let stepY;
                    
                    let hit = 0;
                    let side = 0;
                    let type = 0;
                    
                    if (rayDirX < 0) {
                        stepX = -1;
                        sideDistX = (this.pos.x - mapX) * deltaDistX;
                    } else {
                        stepX = 1;
                        sideDistX = (mapX + 1.0 - this.pos.x) * deltaDistX;
                    }
                    
                    if (rayDirY < 0) {
                        stepY = -1;
                        sideDistY = (this.pos.y - mapY) * deltaDistY;
                    } else {
                        stepY = 1;
                        sideDistY = (mapY + 1.0 - this.pos.y) * deltaDistY;
                    }
                    
                    while (hit === 0) {
                        if (sideDistX < sideDistY) {
                            sideDistX += deltaDistX;
                            mapX += stepX;
                            side = 0;
                        } else {
                            sideDistY += deltaDistY;
                            mapY += stepY;
                            side = 1;
                        }
                        
                        if (mapX < 0 || mapX >= this.mapWidth || mapY < 0 || mapY >= this.mapHeight) {
                            break;
                        }
                        
                        if (this.map[mapY][mapX] > 0) {
                            hit = 1;
                            type = this.map[mapY][mapX];
                        }
                    }
                    
                    if (side === 0) {
                        perpWallDist = (mapX - this.pos.x + (1 - stepX) / 2) / rayDirX;
                    } else {
                        perpWallDist = (mapY - this.pos.y + (1 - stepY) / 2) / rayDirY;
                    }
                    
                    for (let i = 0; i < res; i++) {
                        if (x + i < this.width) {
                            this.zBuffer[x + i] = perpWallDist;
                        }
                    }
                    
                    const lineHeight = Math.floor(this.height / perpWallDist);
                    let drawStart = -lineHeight / 2 + this.height / 2 + this.pitch;
                    let drawEnd = lineHeight / 2 + this.height / 2 + this.pitch;
                    
                    let intensity = 1.0 - (perpWallDist / 4.0); 
                    if (intensity < 0) intensity = 0;
                    if (side === 1) intensity *= 0.5;
                    
                    let r = 160 * intensity;
                    let g = 160 * intensity;
                    let b = 170 * intensity;
                    
                    if (type === 2) {
                        r = 0;
                        g = 255 * intensity;
                        b = 0;
                    }
                    
                    ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
                    ctx.fillRect(x, drawStart, res, drawEnd - drawStart);
                    
                    if (drawEnd < this.height) {
                        // Floor
                        ctx.fillStyle = `rgb(${8 * intensity}, ${8 * intensity}, ${10 * intensity})`;
                        ctx.fillRect(x, drawEnd, res, this.height); // Extend floor to bottom
                    }
                }
                
                if (this.monster.state === 'watching') {
                    const spriteX = this.monster.x - this.pos.x;
                    const spriteY = this.monster.y - this.pos.y;
                    
                    const invDet = 1.0 / (this.plane.x * this.dir.y - this.dir.x * this.plane.y);
                    
                    const transformX = invDet * (this.dir.y * spriteX - this.dir.x * spriteY);
                    const transformY = invDet * (-this.plane.y * spriteX + this.plane.x * spriteY);
                    
                    if (transformY > 0) {
                        const spriteScreenX = Math.floor((this.width / 2) * (1 + transformX / transformY));
                        const spriteHeight = Math.abs(Math.floor(this.height / transformY));
                        const drawStartY = -spriteHeight / 2 + this.height / 2 + this.pitch;
                        const spriteWidth = Math.abs(Math.floor(this.height / transformY));
                        
                        let drawStartX = Math.floor(spriteScreenX - spriteWidth / 2);
                        let drawEndX = Math.floor(spriteScreenX + spriteWidth / 2);
                        
                        
                        if (transformY < 12.0 && drawStartX < this.width && drawEndX > 0 && transformY < this.zBuffer[spriteScreenX]) {
                            this.monster.seenTimer += 16;
                            
                            if (this.monster.seenTimer > 2000 && this.monster.seenTimer < 2150) {
                                ctx.fillStyle = "rgba(255,255,255,0.9)";
                                ctx.fillRect(0, 0, this.width, this.height);
                            } else if (this.monster.seenTimer > 2150) {
                                this.monster.state = 'hidden';
                                this.monster.seenTimer = 0;
                            } else {
                                
                                const eyeW = spriteWidth * 0.25;
                                const eyeH = spriteHeight * 0.12;
                                const eyeY = drawStartY + spriteHeight * 0.3 + (this.monster.bob * spriteHeight); // Apply bobbing
                                ctx.shadowBlur = 40;
                                ctx.shadowColor = "white";
                                ctx.fillStyle = "#fcfcfc";
                                ctx.beginPath();
                                ctx.ellipse(spriteScreenX - spriteWidth * 0.25, eyeY, eyeW, eyeH, 0.1, 0, Math.PI * 2);
                                ctx.fill();
                                ctx.beginPath();
                                ctx.ellipse(spriteScreenX + spriteWidth * 0.25, eyeY, eyeW, eyeH, -0.1, 0, Math.PI * 2);
                                ctx.fill();
                                ctx.shadowBlur = 0;
                                
                                const timeMs = Date.now();
                                const dartState = Math.floor(timeMs / 250);
                                const pX = Math.sin(dartState * 123.45) * eyeW * 0.25;
                                const pY = Math.cos(dartState * 678.90) * eyeH * 0.25;

                                
                                ctx.fillStyle = "#020202";
                                ctx.beginPath();
                                ctx.arc(spriteScreenX - spriteWidth * 0.25 + pX, eyeY + pY, eyeW * 0.65, 0, Math.PI * 2);
                                ctx.fill();
                                ctx.beginPath();
                                ctx.arc(spriteScreenX + spriteWidth * 0.25 + pX, eyeY + pY, eyeW * 0.65, 0, Math.PI * 2);
                                ctx.fill();
                                
                                
                                ctx.fillStyle = "#ffffff";
                                ctx.beginPath();
                                ctx.arc(spriteScreenX - spriteWidth * 0.25 + pX + eyeW*0.12, eyeY + pY - eyeH*0.25, eyeW * 0.12, 0, Math.PI * 2);
                                ctx.fill();
                                ctx.beginPath();
                                ctx.arc(spriteScreenX + spriteWidth * 0.25 + pX + eyeW*0.12, eyeY + pY - eyeH*0.25, eyeW * 0.12, 0, Math.PI * 2);
                                ctx.fill();
                            }
                        }
                    }
                    
                    
                } 
                
                                const distToExit = Math.sqrt(Math.pow(this.exitPos.x - this.pos.x, 2) + Math.pow(this.exitPos.y - this.pos.y, 2));
                const maxDist = Math.sqrt(this.mapWidth*this.mapWidth + this.mapHeight*this.mapHeight);
                const progress = Math.max(0, Math.min(1, 1 - (distToExit / maxDist)));
                
                const barWidth = this.width * 0.4;
                const barHeight = 15;
                const barX = (this.width - barWidth) / 2;
                const barY = this.height - 40;
                
                ctx.fillStyle = "#000";
                ctx.fillRect(barX - 2, barY - 2, barWidth + 4, barHeight + 4);
                ctx.fillStyle = "#222";
                ctx.fillRect(barX, barY, barWidth, barHeight);
                
                ctx.fillStyle = "#1eef1e";
                ctx.shadowBlur = 10;
                ctx.shadowColor = "#1eef1e";
                ctx.fillRect(barX, barY, barWidth * progress, barHeight);
                ctx.shadowBlur = 0;
                
                ctx.fillStyle = "#000";
                for(let i=1; i<10; i++) {
                    ctx.fillRect(barX + (barWidth * (i/10)), barY, 2, barHeight);
                }
                
                                const fRadius = Math.min(this.width, this.height) * 0.7;
                const grad = ctx.createRadialGradient(this.width / 2, this.height / 2, fRadius * 0.3, this.width / 2, this.height / 2, fRadius);
                grad.addColorStop(0, "rgba(0,0,0,0)");
                grad.addColorStop(0.7, "rgba(0,0,0,0.85)");
                grad.addColorStop(1, "rgba(0,0,0,1)");
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, this.width, this.height);
                
                                if (Input.keys['tab']) {
                    const mapSize = 150;
                    const mapX = this.width - mapSize - 20;
                    const mapY = 20;
                    const cellSize = mapSize / this.map.length;
                    
                    ctx.fillStyle = "rgba(0,0,0,0.8)";
                    ctx.fillRect(mapX, mapY, mapSize, mapSize);
                    
                    for (let y = 0; y < this.map.length; y++) {
                        for (let x = 0; x < this.map[0].length; x++) {
                            if (this.map[y][x] > 0) {
                                ctx.fillStyle = this.map[y][x] === 5 ? "#00ff00" : "#444";
                                ctx.fillRect(mapX + x * cellSize, mapY + y * cellSize, cellSize, cellSize);
                            }
                        }
                    }
                    
                    
                    ctx.fillStyle = "#ff0000";
                    ctx.beginPath();
                    ctx.arc(mapX + this.pos.x * cellSize, mapY + this.pos.y * cellSize, cellSize, 0, Math.PI * 2);
                    ctx.fill();
                    
                    
                    if (this.monster.state === 'stalking') {
                        ctx.fillStyle = "#ffffff";
                        ctx.beginPath();
                        ctx.arc(mapX + this.monster.pos.x * cellSize, mapY + this.monster.pos.y * cellSize, cellSize * 1.5, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    
                    ctx.fillStyle = "white";
                    ctx.font = "12px Space Mono";
                    ctx.textAlign = "right";
                    ctx.fillText("MINIMAP ACTIVE", this.width - 20, mapSize + 40);
                }

            }
        }

        class GameEngine {
            constructor() {
                window.currentGameEngine = this;
                
                this.canvas = document.getElementById('game-canvas');
                this.ctx = this.canvas.getContext('2d');
                this.currentState = 'MENU';
                
                this.score = 0;
                this.combo = 1;
                this.comboTimer = 0;
                this.comboCounter = 0;
                this.difficulty = 1.0;
                this.nextRedFlyScore = 1000;
                
                this.fireflies = [];
                this.particles = [];
                this.texts = [];
                this.backrooms = null;
                this.lastTime = 0;
                
                this.bindUI();
                this.resize();
                
                window.addEventListener('resize', () => this.resize());
                
                Input.on('pauseToggle', () => {
                    if (this.currentState === 'PLAYING' || this.currentState === 'PLAYING_HORROR') {
                        if (document.pointerLockElement) {
                            document.exitPointerLock();
                        }
                        this.changeState('PAUSED');
                    } else if (this.currentState === 'PAUSED') {
                        if (this.backrooms) {
                            this.changeState('PLAYING_HORROR');
                            this.canvas.requestPointerLock = this.canvas.requestPointerLock || this.canvas.mozRequestPointerLock;
                            this.canvas.requestPointerLock();
                        } else {
                            this.changeState('PLAYING');
                        }
                    }
                });
            }

            resize() {
                this.width = this.canvas.width = window.innerWidth;
                this.height = this.canvas.height = window.innerHeight;
            }

            bindUI() {
                this.screens = {
                    menu: document.getElementById('screen-menu'),
                    settings: document.getElementById('screen-settings'),
                    pause: document.getElementById('screen-pause'),
                    hud: document.getElementById('hud')
                };
                
                this.ui = {
                    score: document.getElementById('score-value'),
                    combo: document.getElementById('combo-value'),
                    comboFill: document.getElementById('combo-bar-fill'),
                    instruction: document.getElementById('instruction-hud')
                };
                
                document.getElementById('btn-start').addEventListener('click', () => {
                    if (document.documentElement.requestFullscreen) {
                        document.documentElement.requestFullscreen().catch(e => {});
                    }
                    this.startGame();
                });
                
                document.getElementById('btn-settings-open').addEventListener('click', () => {
                    this.screens.menu.classList.add('hidden');
                    this.screens.settings.classList.remove('hidden');
                });
                
                document.getElementById('btn-settings-close').addEventListener('click', () => {
                    this.screens.settings.classList.add('hidden');
                    this.screens.menu.classList.remove('hidden');
                });
                
                document.getElementById('btn-pause').addEventListener('click', () => {
                    if (document.pointerLockElement) {
                        document.exitPointerLock();
                    }
                    this.changeState('PAUSED');
                });
                
                document.getElementById('btn-resume').addEventListener('click', () => {
                    if (this.backrooms) {
                        this.changeState('PLAYING_HORROR');
                        this.canvas.requestPointerLock = this.canvas.requestPointerLock || this.canvas.mozRequestPointerLock;
                        this.canvas.requestPointerLock();
                    } else {
                        this.changeState('PLAYING');
                    }
                });
                
                document.getElementById('btn-quit').addEventListener('click', () => {
                    if (document.exitFullscreen) {
                        document.exitFullscreen().catch(e => {});
                    }
                    this.backrooms = null;
                    Synth.stopHorrorAudio();
                    customMusicPlayer.play().catch(e => {});
                    this.changeState('MENU');
                });
            }

            changeState(newState) {
                this.currentState = newState;
                Object.values(this.screens).forEach(s => s.classList.add('hidden'));
                
                if (newState === 'MENU') {
                    this.screens.menu.classList.remove('hidden');
                    this.initEntities();
                } else if (newState === 'PLAYING') {
                    this.screens.hud.classList.remove('hidden');
                    this.ui.instruction.innerText = "Press and hold to track fireflies";
                    this.ui.instruction.id = "instruction-hud";
                } else if (newState === 'PLAYING_HORROR') {
                    this.screens.hud.classList.remove('hidden');
                    this.ui.instruction.innerText = "Use WASD to move. Mouse to look. Find the green light.";
                    this.ui.instruction.id = "horror-hud-text";
                } else if (newState === 'PAUSED') {
                    this.screens.pause.classList.remove('hidden');
                }
            }

            startGame() {
                this.score = 0;
                this.combo = 1;
                this.comboTimer = 0;
                this.comboCounter = 0;
                this.difficulty = 1.0;
                this.nextRedFlyScore = 1000;
                this.backrooms = null;
                
                this.initEntities();
                this.updateHUD();
                this.changeState('PLAYING');
            }

            initEntities() {
                this.fireflies = [];
                this.particles = [];
                this.texts = [];
                
                let count = 35;
                if (Settings.swarm === 'FEW') {
                    count = 15;
                }
                if (Settings.swarm === 'SWARM') {
                    count = 60;
                }
                
                for (let i = 0; i < count; i++) {
                    this.fireflies.push(new Firefly(this, true));
                }
            }

            onFireflyCaptured(f) {
                if (f.isRed) {
                    this.triggerBackrooms();
                    return;
                }
                
                const pts = f.points * this.combo;
                this.score += pts;
                
                this.comboTimer = Math.min(100, this.comboTimer + 35);
                this.comboCounter++;
                
                if (this.comboCounter >= 4) {
                    this.combo++;
                    this.comboCounter = 0;
                    
                    this.ui.combo.classList.add('shake');
                    setTimeout(() => this.ui.combo.classList.remove('shake'), 300);
                    
                    this.comboTimer = 50;
                    Synth.playComboUp();
                    this.difficulty = Math.min(2.5, this.difficulty + 0.05);
                    
                    let maxSwarm = Settings.swarm === 'SWARM' ? 100 : (Settings.swarm === 'FEW' ? 30 : 60);
                    if (this.fireflies.length < maxSwarm) {
                        this.fireflies.push(new Firefly(this, false));
                    }
                }
                
                if (this.score >= this.nextRedFlyScore) {
                    this.nextRedFlyScore += Math.floor(1000 + Math.random() * 1500);
                    this.fireflies.push(new Firefly(this, false, true));
                }
                
                Synth.playCapture(this.combo);
                
                const numParticles = Math.min(40, 15 + (this.combo * 3));
                for (let p = 0; p < numParticles; p++) {
                    this.particles.push(new Particle(f.pos.x, f.pos.y, f.r, f.g, f.b, this.combo));
                }
                
                const scale = f.type === 'gold' ? 1.5 : 1.0;
                this.texts.push(new FloatingText(f.pos.x, f.pos.y - 20, `+${pts}`, `${f.r},${f.g},${f.b}`, scale));
                
                this.ui.score.style.transform = 'scale(1.15)';
                setTimeout(() => this.ui.score.style.transform = 'scale(1)', 100);
            }

            triggerBackrooms() {
                if (document.documentElement.requestFullscreen) {
                    document.documentElement.requestFullscreen().catch(e => {});
                }
                
                this.canvas.requestPointerLock = this.canvas.requestPointerLock || this.canvas.mozRequestPointerLock;
                this.canvas.requestPointerLock();
                
                                customMusicPlayer.pause();
                Synth.startHorrorAudio();
                
                const flash = document.getElementById('glitch-flash');
                flash.style.opacity = 1;
                
                this.backrooms = new BackroomsEngine(this.width, this.height, this);
                this.changeState('PLAYING_HORROR');
                
                setTimeout(() => { flash.style.opacity = 0; }, 150);
                setTimeout(() => { flash.style.opacity = 1; }, 300);
                setTimeout(() => { flash.style.opacity = 0; }, 600);
            }

            updateHUD() {
                this.ui.score.innerText = this.score.toLocaleString();
                this.ui.combo.innerText = `x${this.combo}`;
                this.ui.comboFill.style.width = `${this.comboTimer}%`;
                
                if (this.combo >= 15) {
                    this.ui.comboFill.style.background = 'var(--glow-accent)';
                    this.ui.combo.style.color = 'var(--glow-accent)';
                } else if (this.combo >= 8) {
                    this.ui.comboFill.style.background = 'var(--glow-secondary)';
                    this.ui.combo.style.color = 'var(--glow-secondary)';
                } else if (this.combo > 1) {
                    this.ui.comboFill.style.background = 'var(--gold-leaf)';
                    this.ui.combo.style.color = 'var(--gold-leaf)';
                } else {
                    this.ui.comboFill.style.background = 'rgba(255,255,255,0.3)';
                    this.ui.combo.style.color = 'var(--ui-muted)';
                }
            }

            tick(currentTime) {
                if (!this.lastTime) {
                    this.lastTime = currentTime;
                }
                
                const deltaTime = Math.min(currentTime - this.lastTime, 100);
                this.lastTime = currentTime;
                
                if (this.currentState === 'PLAYING') {
                    this.ctx.fillStyle = 'rgba(5, 5, 8, 0.4)';
                    this.ctx.fillRect(0, 0, this.width, this.height);
                    
                    if (this.comboTimer > 0) {
                        const drainSpeed = 0.08 + (this.combo * 0.01);
                        this.comboTimer -= drainSpeed * (deltaTime / 16);
                        
                        if (this.comboTimer <= 0) {
                            this.comboTimer = 0;
                            this.combo = 1;
                            this.comboCounter = 0;
                            this.difficulty = Math.max(1.0, this.difficulty - 0.1);
                        }
                    }
                    
                    this.updateHUD();
                    
                    this.fireflies.forEach(f => f.update(currentTime, deltaTime));
                    
                    this.particles = this.particles.filter(p => p.life > 0);
                    this.particles.forEach(p => p.update());
                    
                    this.texts = this.texts.filter(t => t.life > 0);
                    this.texts.forEach(t => t.update());
                    
                    this.fireflies.forEach(f => f.draw(this.ctx));
                    this.particles.forEach(p => p.draw(this.ctx));
                    this.texts.forEach(t => t.draw(this.ctx));
                    
                } else if (this.currentState === 'PLAYING_HORROR') {
                    if (customMusicPlayer && !customMusicPlayer.paused) {
                        customMusicPlayer.pause();
                    }
                    if (this.backrooms) {
                        const won = this.backrooms.update(deltaTime);
                        this.backrooms.render(this.ctx);
                        
                        if (won) {
                            if (document.exitPointerLock) {
                                document.exitPointerLock();
                            }
                            
                            Synth.stopHorrorAudio();
                            
                            if (Settings.musicVol > 0 && !customMusicPlayer.muted) {
                                customMusicPlayer.play().catch(e => {});
                            }
                            
                            const flash = document.getElementById('glitch-flash');
                            flash.style.opacity = 1;
                            
                            setTimeout(() => {
                                flash.style.opacity = 0;
                                if(this.backrooms && this.backrooms.destroy) this.backrooms.destroy();
                                this.backrooms = null;
                                this.changeState('PLAYING');
                            }, 500);
                        }
                    }
                }
                
                requestAnimationFrame((time) => this.tick(time));
            }

            start() {
                this.initEntities();
                requestAnimationFrame((time) => this.tick(time));
            }
        }

        window.onload = () => {
            const game = new GameEngine();
            game.start();
        };
